n    // TODO: Fix old ESLint errors - see issue #1099\n    // eslint-disable-next-line eqeqeq\n    if (step != undefined || step != null) {\n      range.setAttribute('step', step);\n    }\n    this.shadowRoot.appendChild(range);\n  }\n}\n"],mappings:"AAAA,OAAOA,MAAM,MAAM,0BAA0B;AAC7C,OAAOC,SAAS,MAAM,4CAA4C;AAClE,OAAOC,eAAe,MAAM,mDAAmD;AAC/E,eAAe,MAAMC,KAAK,SAASC,WAAW,CAAC;EAC7CC,WAAWA,CAAA,EAAG;IACZ;IACA,KAAK,EAAE;IACP;IACA,IAAI,CAACC,YAAY,CAAC;MAAEC,IAAI,EAAE;IAAO,CAAC,CAAC;EACrC;EAEAC,iBAAiBA,CAAA,EAAG;IAClB;IACA,IAAMC,UAAU,GAAGC,QAAQ,CAACC,aAAa,CAAC,OAAO,CAAC;IAClDF,UAAU,CAACG,WAAW,GAAGV,eAAe;IACxC,IAAMW,cAAc,GAAGH,QAAQ,CAACC,aAAa,CAAC,OAAO,CAAC;IACtDE,cAAc,CAACD,WAAW,GAAGX,SAAS;IACtC,IAAMa,WAAW,GAAGJ,QAAQ,CAACC,aAAa,CAAC,OAAO,CAAC;IACnDG,WAAW,CAACF,WAAW,GAAGZ,MAAM;IAChC,IAAI,CAACe,UAAU,CAACC,WAAW,CAACP,UAAU,CAAC;IACvC,IAAI,CAACM,UAAU,CAACC,WAAW,CAACH,cAAc,CAAC;IAC3C,IAAI,CAACE,UAAU,CAACC,WAAW,CAACF,WAAW,CAAC;IAExC,IAAMG,QAAQ,GAAG,IAAI,CAACC,YAAY,CAAC,eAAe,CAAC;IAEnD,IAAMC,GAAG,GAAG,IAAI,CAACD,YAAY,CAAC,UAAU,CAAC;IAEzC,IAAME,GAAG,GAAG,IAAI,CAACF,YAAY,CAAC,UAAU,CAAC;IAEzC,IAAMG,IAAI,GAAG,IAAI,CAACH,YAAY,CAAC,WAAW,CAAC;IAC3C,IAAMI,KAAK,GAAGZ,QAAQ,CAACC,aAAa,CAAC,OAAO,CAAC;IAC7CW,KAAK,CAACC,IAAI,GAAG,OAAO;IACpBD,KAAK,CAACE,SAAS,GAAG,YAAY;;IAE9B;IACA;IACA,IAAIP,QAAQ,IAAI,MAAM,EAAE;MACtBK,KAAK,CAACL,QAAQ,GAAG,IAAI;IACvB;;IAEA;IACA;IACA,IAAIE,GAAG,IAAIM,SAAS,IAAIN,GAAG,IAAI,IAAI,EAAE;MACnCG,KAAK,CAACI,YAAY,CAAC,KAAK,EAAEP,GAAG,CAAC;IAChC;;IAEA;IACA;IACA,IAAIC,GAAG,IAAIK,SAAS,IAAIL,GAAG,IAAI,IAAI,EAAE;MACnCE,KAAK,CAACI,YAAY,CAAC,KAAK,EAAEN,GAAG,CAAC;IAChC;;IAEA;IACA;IACA,IAAIC,IAAI,IAAII,SAAS,IAAIJ,IAAI,IAAI,IAAI,EAAE;MACrCC,KAAK,CAACI,YAAY,CAAC,MAAM,EAAEL,IAAI,CAAC;IAClC;IACA,IAAI,CAACN,UAAU,CAACC,WAAW,CAACM,KAAK,CAAC;EACpC;AACF"},_coverageSchema:"1a1c01bbd47fc00a2c39e90264f33305004495a9",hash:"0a3e9f90d0d2db0eae2f266fa7b443ed1fbae022"},coverage=global[gcv]||(global[gcv]={});coverage[path]&&"0a3e9f90d0d2db0eae2f266fa7b443ed1fbae022"===coverage[path].hash||(coverage[pat